// Compares the token WhatsApp sends against our stored verify token.
// Set WHATSAPP_VERIFY_TOKEN in n8n Settings > Environment Variables (or .env)
const query = $input.first().json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

const expectedToken = $env.WHATSAPP_VERIFY_TOKEN || 'CHANGE_ME_VERIFY_TOKEN';

if (mode === 'subscribe' && token === expectedToken) {
  return [{ json: { ok: true, challenge: challenge } }];
}
return [{ json: { ok: false, challenge: '' } }];

// Pulls the relevant fields out of the WhatsApp Cloud API payload.
// Returns hasMessage=false for non-message events (e.g. delivery/read receipts)
const body = $input.first().json.body || {};

try {
  const entry = body.entry?.[0];
  const change = entry?.changes?.[0];
  const value = change?.value;
  const message = value?.messages?.[0];

  if (!message) {
    return [{ json: { hasMessage: false } }];
  }

  const from = message.from; // customer's WhatsApp number
  const messageId = message.id;
  const contactName = value.contacts?.[0]?.profile?.name || '';
  let text = '';

  if (message.type === 'text') {
    text = message.text.body;
  } else if (message.type === 'interactive') {
    text = message.interactive?.button_reply?.title
      || message.interactive?.list_reply?.title
      || '';
  } else {
    // unsupported message type (image, audio, location, etc.)
    return [{ json: { hasMessage: false } }];
  }

  return [{
    json: {
      hasMessage: true,
      from,
      messageId,
      contactName,
      text: (text || '').trim()
    }
  }];
} catch (err) {
  return [{ json: { hasMessage: false, error: err.message } }];
}

