// Safely parses the LLM's JSON classification. Falls back to 'other'
// if Ollama returns malformed JSON so the flow never breaks.
const original = $('Extract Message').first().json;
let content = $input.first().json.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(content);
} catch (err) {
  parsed = { intent: 'other', keywords: [], job_name: '' };
}

const allowed = ['job_discovery', 'apply_job', 'faq', 'greeting', 'other'];
if (!allowed.includes(parsed.intent)) parsed.intent = 'other';
if (!Array.isArray(parsed.keywords)) parsed.keywords = [];
if (typeof parsed.job_name !== 'string') parsed.job_name = '';

return [{
  json: {
    from: original.from,
    text: original.text,
    contactName: original.contactName,
    intent: parsed.intent,
    keywords: parsed.keywords.map(k => String(k).toLowerCase()),
    job_name: parsed.job_name
  }
}];

// Ranks open jobs by keyword overlap against Position/Department/Skills.
// Returns the top 5 matches, or all open jobs if no keywords matched.
const intentData = $('Parse Intent').first().json;
const keywords = intentData.keywords.length
  ? intentData.keywords
  : intentData.text.toLowerCase().split(/\s+/);

const jobs = $input.all().map(item => item.json);

function score(job) {
  const haystack = [job.Position, job.Department, job.Skills]
    .join(' ')
    .toLowerCase();
  let s = 0;
  for (const kw of keywords) {
    if (kw.length > 2 && haystack.includes(kw)) s += 1;
  }
  return s;
}

const openJobs = jobs.filter(j => (j.Status || '').trim().toLowerCase() === 'open');
const scored = openJobs
  .map(j => ({ job: j, score: score(j) }))
  .sort((a, b) => b.score - a.score);

const hasMatches = scored.some(s => s.score > 0);
const results = (hasMatches ? scored.filter(s => s.score > 0) : scored)
  .slice(0, 5)
  .map(s => s.job);

return [{
  json: {
    from: intentData.from,
    matches: results
  }
}];

const data = $input.first().json;
const jobs = data.matches;

let reply;
if (!jobs.length) {
  reply = "Sorry, we don't have any matching openings right now. Would you like to see all current job openings instead?";
} else {
  const lines = jobs.map((j, i) => {
    return `${i + 1}. *${j.Position}*\n📍 ${j.Location}\n💰 ${j.Salary}\n🛠 Skills: ${j.Skills}\n\nApply Here:\n${j['Apply URL']}`;
  });
  reply = `We currently have these openings:\n\n${lines.join('\n\n--------------------------------\n\n')}\n\nReply with the job title if you'd like to apply.`;
}

return [{ json: { from: data.from, replyText: reply } }];

// Matches the candidate's requested job title against the CSV (case-insensitive,
// partial match) and checks whether the role is still open.
const intentData = $('Parse Intent').first().json;
const requested = (intentData.job_name || intentData.text || '').toLowerCase().trim();

const jobs = $input.all().map(item => item.json);

let match = jobs.find(j => (j.Position || '').toLowerCase() === requested);
if (!match) {
  match = jobs.find(j => requested && (j.Position || '').toLowerCase().includes(requested));
}
if (!match) {
  match = jobs.find(j => requested && requested.includes((j.Position || '').toLowerCase()) && j.Position);
}

return [{
  json: {
    from: intentData.from,
    found: !!match,
    isOpen: match ? (match.Status || '').trim().toLowerCase() === 'open' : false,
    position: match ? match.Position : (intentData.job_name || ''),
    applyUrl: match ? match['Apply URL'] : ''
  }
}];

const d = $input.first().json;
let reply;

if (!d.found) {
  reply = "I couldn't find that position. Could you tell me the exact job title? Or type 'jobs' to see current openings.";
} else if (!d.isOpen) {
  reply = `Sorry, the ${d.position} position is currently closed.\n\nWould you like to see similar openings?`;
} else {
  reply = `Great! You can apply for the ${d.position} position using the link below:\n\n${d.applyUrl}\n\nPlease complete the application form and upload your latest resume.\n\nGood luck!`;
}

return [{ json: { from: d.from, replyText: reply } }];

// Scores each FAQ question by word overlap with the candidate's message.
const intentData = $('Parse Intent').first().json;
const queryWords = new Set(
  (intentData.text || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2)
);

const faqs = $input.all().map(item => item.json);

function score(faq) {
  const qWords = (faq.Question || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2);
  let s = 0;
  for (const w of qWords) {
    if (queryWords.has(w)) s += 1;
  }
  return s;
}

let best = null;
let bestScore = 0;
for (const f of faqs) {
  const s = score(f);
  if (s > bestScore) {
    bestScore = s;
    best = f;
  }
}

return [{
  json: {
    from: intentData.from,
    found: !!best && bestScore > 0,
    answer: best ? best.Answer : ''
  }
}];

const d = $input.first().json;
const reply = d.found
  ? d.answer
  : "I don't have that information yet. You can email hr@company.com and our team will help you directly.";

return [{ json: { from: d.from, replyText: reply } }];

